    # FP in a column blocks horizontal fill at that column
    # FP at top of column projects down, but FP at bottom projects up

    # Look at each column: if there's an FP in this column, fill from FP towards source row
    for c in range(m):
        fpr = -1  # FP row position in this column
        for r in range(n):
            if grid[r][c] == fp:
                fpr = r

        src_r = 5 if grid[5][c] == source_color else -1  # source row for this column

        if fpr != -1 and src_r != -1:
            # Fill from FP down to source
            for r in range(fpr, src_r):
